function drawFingerToBody(f, bctx) {
  const ext = f.extend == null ? 46 : f.extend;
  const fa = fingerFrame(f, 0);
  const { left, right } = fingerOutline(f, ext);
  const extBase = { x: fa.bx - fa.dirx * ext, y: fa.by - fa.diry * ext };

  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  left.concat(right).forEach((p) => {
    if (p.x < minX) minX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.x > maxX) maxX = p.x;
    if (p.y > maxY) maxY = p.y;
  });
  const pad = 16;
  const x0 = Math.floor(minX - pad);
  const y0 = Math.floor(minY - pad);
  const w = Math.ceil(maxX + pad) - x0;
  const h = Math.ceil(maxY + pad) - y0;
  if (w <= 0 || h <= 0) return;

  const scale = 2;
  const scratch = document.createElement('canvas');
  scratch.width = Math.ceil(w * scale);
  scratch.height = Math.ceil(h * scale);
  const sctx = scratch.getContext('2d');
  sctx.scale(scale, scale);
  sctx.translate(-x0, -y0);

  const prev = ctx;
  ctx = sctx;
  drawFinger(f);
  ctx = prev;

  sctx.globalCompositeOperation = 'destination-in';
  const fade = sctx.createLinearGradient(extBase.x, extBase.y, fa.bx, fa.by);
  fade.addColorStop(0, 'rgba(0, 0, 0, 0)');
  fade.addColorStop(0.6, 'rgba(0, 0, 0, 0.55)');
  fade.addColorStop(1, 'rgba(0, 0, 0, 1)');
  sctx.fillStyle = fade;
  sctx.fillRect(x0, y0, w, h);

  bctx.save();
  bctx.shadowColor = 'rgba(138, 70, 54, 0.2)';
  bctx.shadowBlur = 12;
  bctx.shadowOffsetX = 2;
  bctx.shadowOffsetY = 6;
  bctx.drawImage(scratch, x0, y0, w, h);
  bctx.restore();
}

function renderHandBody() {
  const scale = 2;
  const off = document.createElement('canvas');
  off.width = Math.ceil(DW * scale);
  off.height = Math.ceil(DH * scale);
  const bctx = off.getContext('2d');
  bctx.scale(scale, scale);

  const prev = ctx;
  ctx = bctx;
  drawPalm();
  FINGERS.forEach((f) => drawFingerToBody(f, bctx));
  ctx = prev;

  bodyCanvas = off;
}

